"""Helpers for building OpenAI tool schemas and reading tool calls."""

import inspect
import json
from typing import Any, Callable, Optional, Union, get_args, get_origin

__all__ = [
    "convert_func_to_oai_tool",
    "get_tool_call_name",
    "get_tool_call_args",
]

# Map common Python annotations to JSON schema types.
_PY_TYPE_TO_JSON: dict[Any, str] = {
    str: "string",
    int: "integer",
    float: "number",
    bool: "boolean",
    list: "array",
    dict: "object",
}


def _annotation_to_json_type(annotation: Any) -> str:
    """Map a Python type annotation to a JSON schema type string.

    ``str``/``int``/``float``/``bool``/``list``/``dict`` map to their JSON
    counterparts (generic containers like ``list[int]`` map to the
    container type); anything else defaults to ``"string"``.
    """
    if annotation is inspect.Parameter.empty:
        return "string"
    origin = get_origin(annotation)
    if origin is not None:
        if origin in _PY_TYPE_TO_JSON:
            return _PY_TYPE_TO_JSON[origin]
        if origin is Union:
            non_none = [a for a in get_args(annotation) if a is not type(None)]
            if non_none:
                return _annotation_to_json_type(non_none[0])
        return "string"
    return _PY_TYPE_TO_JSON.get(annotation, "string")


def _parse_docstring(docstring: Optional[str]) -> tuple[str, dict[str, str]]:
    """Parse a function docstring into a description and per-arg descriptions.

    The first non-empty line becomes the function description. Lines under
    an ``Args:`` (or ``Parameters``) section of the form
    ``name: description`` become per-parameter descriptions.
    """
    if not docstring:
        return "", {}
    lines = docstring.expandtabs().splitlines()
    description = ""
    for line in lines:
        stripped = line.strip()
        if stripped:
            description = stripped
            break
    arg_descriptions: dict[str, str] = {}
    in_args = False
    for line in lines:
        stripped = line.strip()
        header = stripped.rstrip(":")
        if header in ("Args", "Arguments", "Parameters"):
            in_args = True
            continue
        if in_args:
            if not stripped:
                continue
            if line == line.lstrip() and not stripped.startswith("-"):
                # Dedented line: end of the args section.
                in_args = False
                continue
            if ":" in stripped:
                name, _, desc = stripped.partition(":")
                name = name.strip().split()[0] if name.strip() else ""
                if name:
                    arg_descriptions[name] = desc.strip()
    return description, arg_descriptions


def convert_func_to_oai_tool(func: Callable) -> dict:
    """Build an OpenAI chat tool schema from a Python function.

    Inspects the function's signature and docstring to produce a schema of
    the form::

        {"type": "function",
         "function": {"name": ..., "description": ...,
                      "parameters": <JSON schema>}}

    Annotations ``str``/``int``/``float``/``bool``/``list``/``dict`` map to
    their JSON schema types; anything else defaults to ``"string"``.
    Parameters without defaults are marked as required.

    Args:
        func: The Python function to describe.

    Returns:
        A dict matching the OpenAI chat tool schema format.
    """
    description, arg_descriptions = _parse_docstring(func.__doc__)
    sig = inspect.signature(func)
    properties: dict[str, dict[str, str]] = {}
    required: list[str] = []
    for name, param in sig.parameters.items():
        if param.kind in (
            inspect.Parameter.VAR_POSITIONAL,
            inspect.Parameter.VAR_KEYWORD,
        ):
            continue
        prop: dict[str, str] = {"type": _annotation_to_json_type(param.annotation)}
        if name in arg_descriptions:
            prop["description"] = arg_descriptions[name]
        properties[name] = prop
        if param.default is inspect.Parameter.empty:
            required.append(name)
    return {
        "type": "function",
        "function": {
            "name": func.__name__,
            "description": description,
            "parameters": {
                "type": "object",
                "properties": properties,
                "required": required,
            },
        },
    }


def _get_function_obj(tool_call: Any) -> Any:
    """Return the inner function object of a tool call (dict or pydantic)."""
    if isinstance(tool_call, dict):
        return tool_call.get("function", {})
    return getattr(tool_call, "function", None)


def get_tool_call_name(tool_call: Any) -> str:
    """Get the function name of a tool call.

    Args:
        tool_call: An openai pydantic tool-call object or a plain dict of
            the form ``{"function": {"name": ..., "arguments": ...}}``.

    Returns:
        The tool call's function name as a string.
    """
    fn = _get_function_obj(tool_call)
    if isinstance(fn, dict):
        return str(fn.get("name", ""))
    return str(getattr(fn, "name", "") or "")


def get_tool_call_args(tool_call: Any) -> dict:
    """Get the parsed arguments of a tool call.

    Args:
        tool_call: An openai pydantic tool-call object or a plain dict.

    Returns:
        The arguments JSON string parsed via ``json.loads`` into a dict.
        Returns ``{}`` if the arguments are missing or not valid JSON.
    """
    fn = _get_function_obj(tool_call)
    if isinstance(fn, dict):
        raw = fn.get("arguments", "")
    else:
        raw = getattr(fn, "arguments", "") or ""
    if isinstance(raw, dict):
        return raw
    try:
        parsed = json.loads(raw)
    except (json.JSONDecodeError, TypeError):
        return {}
    return parsed if isinstance(parsed, dict) else {}

"""Simple example tool functions usable with ``convert_func_to_oai_tool``."""

import ast
import operator
from datetime import datetime

__all__ = ["search_web", "calculator", "get_current_time"]


def search_web(query: str) -> str:
    """Search the web for a query.

    Args:
        query: The search query string.

    Returns:
        A canned stub result string (no real search is performed).
    """
    return f"Search results for '{query}': No results found (stub implementation)."


# Allowed binary operators for the calculator.
_BIN_OPS = {
    ast.Add: operator.add,
    ast.Sub: operator.sub,
    ast.Mult: operator.mul,
    ast.Div: operator.truediv,
}

# Allowed unary operators for the calculator.
_UNARY_OPS = {
    ast.UAdd: operator.pos,
    ast.USub: operator.neg,
}


def _eval_node(node: ast.AST) -> float:
    """Recursively evaluate an arithmetic AST node.

    Only numeric literals, ``+ - * /`` binary operations, unary ``+ -``,
    and parentheses are allowed.
    """
    if isinstance(node, ast.Expression):
        return _eval_node(node.body)
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)):
        return node.value
    if isinstance(node, ast.BinOp) and type(node.op) in _BIN_OPS:
        return _BIN_OPS[type(node.op)](_eval_node(node.left), _eval_node(node.right))
    if isinstance(node, ast.UnaryOp) and type(node.op) in _UNARY_OPS:
        return _UNARY_OPS[type(node.op)](_eval_node(node.operand))
    raise ValueError(
        f"Unsupported expression element: {ast.dump(node)}. "
        "Only numbers and + - * / with parentheses are allowed."
    )


def calculator(expression: str) -> str:
    """Evaluate an arithmetic expression.

    Supports only numbers, the operators +, -, *, /, and parentheses.

    Args:
        expression: The arithmetic expression to evaluate, e.g. "(2 + 3) * 4".

    Returns:
        The result of the evaluation as a string.
    """
    try:
        tree = ast.parse(expression, mode="eval")
        result = _eval_node(tree)
    except (SyntaxError, ValueError, ZeroDivisionError) as e:
        return f"Error: {e}"
    if isinstance(result, float) and result.is_integer():
        return str(int(result))
    return str(result)


def get_current_time() -> str:
    """Get the current local date and time.

    Returns:
        The current local time formatted as "YYYY-MM-DD HH:MM:SS".
    """
    return datetime.now().strftime("%Y-%m-%d %H:%M:%S")

